# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs, offset=4):
    return [v + offset for v in xs]

# region: fold
def fold(xs, factor=2):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(emit(fold(sift(intake(raw)))))

